import sys

def main():
    legal_roles = ["Project Manager", "Designer", "Developer", "Tester"]
    task = "Implement a user registration feature for an online store"

    print("Welcome to the Role-Based Collaboration Simulator!")
    print(f"Task: {task}\n")
    print("Legal roles:", ", ".join(legal_roles))

    while True:
        first_choice = input("\nChoose the first speaker (or type 'done' to exit): ").strip()
        if first_choice.lower() == "done":
            print("Exiting without starting collaboration.")
            return
        matched = [role for role in legal_roles if role.lower() == first_choice.lower()]
        if matched:
            current_speaker = matched[0]
            break
        else:
            print(f"Error: '{first_choice}' is not a legal role. Choose from {legal_roles}")

    print(f"\n--- Starting collaboration: {current_speaker} speaks first ---\n")
    spoke_roles = []

    while True:
        print(f"{current_speaker}

